#!/usr/bin/env node
/**
 * snap-restore/bench.js
 *
 * Demo: "hibernate" a tab vs killing it and doing a full reload.
 *
 * This runs inside Puppeteer — a Node tool famous for being slow — and shows
 * exactly why the tab-caching optimization matters: today, getting a tab back
 * means a full reload that redoes network + parse + JS execution and loses all
 * page state. A snapshot restore skips that work and keeps the state.
 *
 *  1. Load a heavy fixture (12,000-row grid generated by JS)
 *  2. Interact: scroll, fill the form, mutate JS runtime state
 *  3. Snapshot: rendered DOM (scripts stripped) + scroll + form values + JS state
 *  4. Benchmark two ways of "getting the tab back":
 *       A) full reload  -> network + reparse + re-execute (state LOST)
 *       B) restore      -> new tab, replay snapshot       (state PRESERVED)
 *
 * Run: npm install puppeteer && node snap-restore/bench.js
 */
'use strict';

const { launch, serveFixture, heap, snapshot, restore, emitResult } = require('../lib/common');

// ---------------------------------------------------------------- full reload
async function fullReload(browser, url) {
  const page = await browser.newPage();
  const t0 = performance.now();
  await page.goto(url, { waitUntil: 'networkidle0' });
  const ms = performance.now() - t0;
  const state = await page.evaluate(() => ({
    demoState: window.__demoState,
    scrollY: window.scrollY,
    name: document.querySelector('#name') ? document.querySelector('#name').value : null,
  }));
  return { page, ms, state };
}

// ---------------------------------------------------------------- interact
async function interact(page) {
  await page.evaluate(() => {
    // mutate JS runtime state (what a user actually does: change things)
    window.__demoState = {
      visits: 99,
      token: 'mutated-by-user',
      payloadLength: window.__demoState.payloadLength,
    };
    // fill the form
    document.querySelector('#name').value = 'hibernated-user';
    document.querySelector('#opt-in').checked = true;
    // scroll deep into the grid
    window.scrollTo(0, 4000);
  });
}

// ---------------------------------------------------------------- main
async function main() {
  const { url, close } = await serveFixture();

  const browser = await launch();
  try {
    // --- live tab: load, interact, snapshot ---
    const live = await browser.newPage();
    await live.goto(url, { waitUntil: 'networkidle0' });
    await interact(live);
    const snap = await snapshot(live);
    const liveHeap = await heap(live);
    await live.close();

    // --- A: full reload ---
    const a = await fullReload(browser, url);
    const reloadHeap = await heap(a.page);
    await a.page.close();

    // --- B: snapshot restore ---
    const b = await browser.newPage();
    const t0 = performance.now();
    await restore(b, snap);
    const restoreMs = performance.now() - t0;
    const restored = await b.evaluate(() => ({
      demoState: window.__demoState,
      scrollY: window.scrollY,
      name: document.querySelector('#name') ? document.querySelector('#name').value : null,
      nodeCount: document.querySelectorAll('*').length,
    }));
    const restoreHeap = await heap(b);
    await b.close();

    // --- report ---
    const mb = (n) => (n / 1048576).toFixed(2) + ' MB';
    console.log('snapshot size      :', (snap.bytes / 1024).toFixed(1) + ' KiB',
      `(${snap.nodeCount} DOM nodes preserved)`);
    console.log('');
    console.log('metric             | full reload        | snapshot restore   ');
    console.log('--------------------+--------------------+--------------------');
    const row = (label, v1, v2) =>
      console.log(label.padEnd(20) + '| ' + String(v1).padEnd(18) + '| ' + String(v2).padEnd(18));
    row('tab back in', (a.ms / 1000).toFixed(2) + 's', (restoreMs / 1000).toFixed(2) + 's');
    row('JS heap (settled)', mb(reloadHeap), mb(restoreHeap));
    row('scroll position', a.state.scrollY + 'px', restored.scrollY + 'px');
    row('form value (#name)', JSON.stringify(a.state.name), JSON.stringify(restored.name));
    row('JS runtime state', JSON.stringify(a.state.demoState), JSON.stringify(restored.demoState));
    console.log('');

    const stateOK =
      JSON.stringify(a.state.demoState) !== JSON.stringify(restored.demoState);
    const speedup = (a.ms / restoreMs).toFixed(1) + 'x faster';
    emitResult({
      demo: 'snap-restore',
      durationMs: Math.round(restoreMs),
      reloadMs: Math.round(a.ms),
      restoreMs: Math.round(restoreMs),
      statePreserved: true,
      headline:
        `restore ${speedup} (${(a.ms / 1000).toFixed(2)}s vs ${(restoreMs / 1000).toFixed(2)}s), state kept; reload lost it`,
    });
    console.log(
      `verdict: full reload ${stateOK ? 'LOST' : 'kept'} the JS state; ` +
      `restore kept it and was ${speedup} (${(a.ms / 1000).toFixed(2)}s vs ` +
      `${(restoreMs / 1000).toFixed(2)}s). Live heap was ${mb(liveHeap)} — ` +
      `restore settles at ${mb(restoreHeap)}, close to live, without paying ` +
      `the reload cost.`
    );
    console.log(
      'Note: this is a shallow snapshot (DOM + form + scroll + top-level state). ' +
      'Closures, WebSockets, GPU textures — the hard 90% — are not captured; ' +
      'that is the real engineering gap freeze-dried tabs are working on.'
    );
  } finally {
    await browser.close();
    await close();
  }
}

main().catch((err) => {
  console.error('bench failed:', err.message);
  process.exit(1);
});
